result.ocaml:
let is_individual_retirement_plan (entity : entity) : bool =
  is_individual_retirement_account entity ||
  is_individual_retirement_annuity entity

let is_substituted_basis_property (property : property) : bool =
  is_transferred_basis_property property ||
  is_exchanged_basis_property property

let qualifies_as_eligible_component_activity (component : eligible_component) : bool =
  extracts_processes_or_recycles_applicable_critical_mineral component ||
  produces_eligible_component_not_critical_mineral component

let excludes_foreign_controlled_entity_rules (entity : entity) : bool =
  regularly_traded_on_national_securities_exchange entity ||
  regularly_traded_on_qualifying_foreign_exchange entity

let is_qualified_facility (facility : facility) : bool =
  is_qualified_facility_45y_b_1 facility ||
  is_qualified_facility_48e_b_3 facility

type manufactured_product = {
  cost : money;
  incorporated_into_facility_upon_completion : bool;
  mined_produced_or_manufactured_by_prohibited_foreign_entity : bool;
}

let is_prohibited_foreign_product (product : manufactured_product) : bool =
  product.incorporated_into_facility_upon_completion &&
  product.mined_produced_or_manufactured_by_prohibited_foreign_entity

let total_direct_costs_attributable_to_prohibited_foreign_products (products : manufactured_product list) : money =
  products
  |> List.filter is_prohibited_foreign_product
  |> List.fold_left (fun acc product -> acc +. product.cost) 0.0

let material_assistance_cost_ratio (products : manufactured_product list) (total_manufactured_product_cost : money) : decimal =
  total_direct_costs_attributable_to_prohibited_foreign_products products /. total_manufactured_product_cost

let has_valid_supplier_certification (component : component) : bool =
  certifies_direct_cost_percentage_not_from_prohibited_entity component ||
  certifies_product_not_produced_by_prohibited_entity component

let includes_supplier_identification (supplier : supplier) : bool =
  has_employer_identification_number supplier ||
  has_foreign_government_identification_number supplier

let is_eligible_component (component : component) : bool =
  is_45x_c1_property component ||
  identified_by_secretary_under_subparagraph_g component

let is_manufactured_product (product : product) : bool =
  is_component_of_qualified_facility product ||
  is_identified_by_secretary product

let meets_substantial_presence_test (individual : person) (election_year : year) : bool =
  present_31_consecutive_days_in_election_year individual election_year &&
  present_75_percent_of_testing_period individual election_year

let testing_period (thirty_one_day_period : date_range) (election_year : year) : date_range =
  { start_date = thirty_one_day_period.start_date; end_date = last_day_of_year election_year }

let present_75_percent_of_testing_period (individual : person) (election_year : year) : bool =
  let period = testing_period (thirty_one_day_period individual election_year) election_year in
  let days_present = days_present_in_period individual period in
  let days_absent_excused = min 5 (days_absent_in_period individual period) in
  let effective_days_present = days_present + days_absent_excused in
  effective_days_present >= (75 * days_in_period period) / 100

let is_student (individual : person) : bool =
  temporarily_present_in_united_states individual &&
  substantially_complies_with_presence_requirements individual

let is_temporarily_present_exempt_individual (person : person) : bool =
  has_status_f_or_m_visa person ||
  is_student_under_j_or_q_visa person
